PRAGMA foreign_keys = ON;
-- Geometrie CERMAT / ctyrlete obory / specifikace 2026-2027.
-- Katalog testu, nikoli prirazeni studentovi.
INSERT OR IGNORE INTO self_check_tests (id,slug,version,title,description,subject,topic,level,estimated_minutes,status)
VALUES ('cermat-geometrie-4lete-2027-v1','cermat-geometrie-4lete-2027',1,'CERMAT 4leté obory — geometrie (42 úloh)','42 autorských úloh / 84 bodů. Úhly, obsahy, Pythagorova věta, kruh, podobnost, měřítko, tělesa a konstrukční úsudek. Podle specifikace 2026/2027. Výsledky a rozbor se ukládají po přiřazení studentovi.','Matematika','Geometrie — CERMAT 4leté', 'ZŠ 9. třída',55,'published');
INSERT OR IGNORE INTO self_check_questions (id,test_id,position,prompt,options_json,correct_answer,explanation,points) VALUES
('cermat-geometrie-4lete-2027-v1-q01','cermat-geometrie-4lete-2027-v1',1,'{"instruction":"Vedlejší úhel k úhlu 47°. Kolik stupňů má?","category":"Úhly a trojúhelníky","hint":"Vedlejší úhly dávají dohromady 180°."}','[{"id":"a","label":"134"},{"id":"b","label":"133"},{"id":"c","label":"132"},{"id":"d","label":"135"}]','b','180 − 47 = 133°.',2),
('cermat-geometrie-4lete-2027-v1-q02','cermat-geometrie-4lete-2027-v1',2,'{"instruction":"Dvě přímky se protínají. Úhel vrcholový k úhlu 68° měří kolik stupňů?","category":"Úhly a trojúhelníky","hint":"Vrcholové úhly jsou shodné."}','[{"id":"a","label":"68"},{"id":"b","label":"70"},{"id":"c","label":"66"},{"id":"d","label":"72"}]','a','Vrcholové úhly jsou stejně velké.',2),
('cermat-geometrie-4lete-2027-v1-q03','cermat-geometrie-4lete-2027-v1',3,'{"instruction":"Trojúhelník má úhly 38° a 71°. Kolik stupňů má třetí úhel?","category":"Úhly a trojúhelníky","hint":"Součet vnitřních úhlů trojúhelníku je 180°."}','[{"id":"a","label":"74"},{"id":"b","label":"68"},{"id":"c","label":"77"},{"id":"d","label":"71"}]','d','180 − 38 − 71 = 71°.',2),
('cermat-geometrie-4lete-2027-v1-q04','cermat-geometrie-4lete-2027-v1',4,'{"instruction":"Vrcholový úhel rovnoramenného trojúhelníku má 46°. Kolik stupňů měří každý úhel při základně?","category":"Úhly a trojúhelníky","hint":"Úhly při základně jsou stejné."}','[{"id":"a","label":"71"},{"id":"b","label":"63"},{"id":"c","label":"67"},{"id":"d","label":"75"}]','c','(180 − 46)/2 = 67°.',2),
('cermat-geometrie-4lete-2027-v1-q05','cermat-geometrie-4lete-2027-v1',5,'{"instruction":"Čtyřúhelník má tři vnitřní úhly 82°, 95° a 107°. Jak velký je čtvrtý?","category":"Úhly a trojúhelníky","hint":"Čtyřúhelník: 360°."}','[{"id":"a","label":"77"},{"id":"b","label":"76"},{"id":"c","label":"75"},{"id":"d","label":"78"}]','b','360 − 82 − 95 − 107 = 76°.',2),
('cermat-geometrie-4lete-2027-v1-q06','cermat-geometrie-4lete-2027-v1',6,'{"instruction":"Přímý úhel je rozdělen na dva. Jeden má 125°. Druhý má kolik stupňů?","category":"Úhly a trojúhelníky","hint":"Přímý úhel má 180°."}','[{"id":"a","label":"55"},{"id":"b","label":"57"},{"id":"c","label":"53"},{"id":"d","label":"59"}]','a','180 − 125 = 55°.',2),
('cermat-geometrie-4lete-2027-v1-q07','cermat-geometrie-4lete-2027-v1',7,'{"instruction":"Obdélník má rozměry 12 cm a 7 cm. Urči obsah v cm².","category":"Obvody a obsahy","hint":"Obsah obdélníku je a × b."}','[{"id":"a","label":"87"},{"id":"b","label":"81"},{"id":"c","label":"90"},{"id":"d","label":"84"}]','d','S = 12 × 7 = 84 cm².',2),
('cermat-geometrie-4lete-2027-v1-q08','cermat-geometrie-4lete-2027-v1',8,'{"instruction":"Obdélník má strany 9 cm a 5 cm. Urči obvod v cm.","category":"Obvody a obsahy","hint":"Obvod = dvakrát součet sousedních stran."}','[{"id":"a","label":"32"},{"id":"b","label":"24"},{"id":"c","label":"28"},{"id":"d","label":"36"}]','c','o = 2(9 + 5) = 28 cm.',2),
('cermat-geometrie-4lete-2027-v1-q09','cermat-geometrie-4lete-2027-v1',9,'{"instruction":"Trojúhelník má základnu 14 cm a příslušnou výšku 9 cm. Urči obsah v cm².","category":"Obvody a obsahy","hint":"Obsah trojúhelníku dělíme dvěma."}','[{"id":"a","label":"64"},{"id":"b","label":"63"},{"id":"c","label":"62"},{"id":"d","label":"65"}]','b','S = 14 × 9 / 2 = 63 cm².',2),
('cermat-geometrie-4lete-2027-v1-q10','cermat-geometrie-4lete-2027-v1',10,'{"instruction":"Rovnoběžník má stranu a = 11 cm a výšku na tuto stranu 5 cm. Urči obsah v cm².","category":"Obvody a obsahy","hint":"Důležitá je výška kolmá na danou stranu."}','[{"id":"a","label":"55"},{"id":"b","label":"57"},{"id":"c","label":"53"},{"id":"d","label":"59"}]','a','S = 11 × 5 = 55 cm².',2),
('cermat-geometrie-4lete-2027-v1-q11','cermat-geometrie-4lete-2027-v1',11,'{"instruction":"Lichoběžník má základny 9 cm a 15 cm, výšku 6 cm. Urči obsah v cm².","category":"Obvody a obsahy","hint":"Průměr základen × výška."}','[{"id":"a","label":"75"},{"id":"b","label":"69"},{"id":"c","label":"78"},{"id":"d","label":"72"}]','d','S = (9 + 15) × 6 / 2 = 72 cm².',2),
('cermat-geometrie-4lete-2027-v1-q12','cermat-geometrie-4lete-2027-v1',12,'{"instruction":"Čtverec má obvod 36 cm. Urči jeho obsah v cm².","category":"Obvody a obsahy","hint":"Nejdříve spočítej délku strany."}','[{"id":"a","label":"85"},{"id":"b","label":"77"},{"id":"c","label":"81"},{"id":"d","label":"89"}]','c','a = 36/4 = 9 cm; S = 9² = 81 cm².',2),
('cermat-geometrie-4lete-2027-v1-q13','cermat-geometrie-4lete-2027-v1',13,'{"instruction":"Pravoúhlý trojúhelník má odvěsny 6 cm a 8 cm. Urči přeponu v cm.","category":"Pythagorova věta","hint":"Přepona je nejdelší strana."}','[{"id":"a","label":"11"},{"id":"b","label":"10"},{"id":"c","label":"9"},{"id":"d","label":"12"}]','b','c = √(6² + 8²) = √100 = 10 cm.',2),
('cermat-geometrie-4lete-2027-v1-q14','cermat-geometrie-4lete-2027-v1',14,'{"instruction":"Přepona má 13 cm a jedna odvěsna 5 cm. Urči druhou odvěsnu v cm.","category":"Pythagorova věta","hint":"U odvěsny se čtverce odečítají."}','[{"id":"a","label":"12"},{"id":"b","label":"14"},{"id":"c","label":"10"},{"id":"d","label":"16"}]','a','b = √(13² − 5²) = 12 cm.',2),
('cermat-geometrie-4lete-2027-v1-q15','cermat-geometrie-4lete-2027-v1',15,'{"instruction":"Obdélník má rozměry 9 cm a 12 cm. Urči jeho úhlopříčku v cm.","category":"Pythagorova věta","hint":"Úhlopříčka rozdělí obdélník na pravoúhlé trojúhelníky."}','[{"id":"a","label":"18"},{"id":"b","label":"12"},{"id":"c","label":"21"},{"id":"d","label":"15"}]','d','u = √(9² + 12²) = 15 cm.',2),
('cermat-geometrie-4lete-2027-v1-q16','cermat-geometrie-4lete-2027-v1',16,'{"instruction":"Pravoúhlý trojúhelník má odvěsny 20 cm a 21 cm. Urči přeponu v cm.","category":"Pythagorova věta","hint":"Dosadíš do c² = a² + b²."}','[{"id":"a","label":"33"},{"id":"b","label":"25"},{"id":"c","label":"29"},{"id":"d","label":"37"}]','c','c = √(400 + 441) = √841 = 29 cm.',2),
('cermat-geometrie-4lete-2027-v1-q17','cermat-geometrie-4lete-2027-v1',17,'{"instruction":"Přepona pravoúhlého trojúhelníku má 25 cm, odvěsna 7 cm. Jak dlouhá je druhá odvěsna v cm?","category":"Pythagorova věta","hint":"Vypočti rozdíl čtverců."}','[{"id":"a","label":"25"},{"id":"b","label":"24"},{"id":"c","label":"23"},{"id":"d","label":"26"}]','b','b = √(625 − 49) = √576 = 24 cm.',2),
('cermat-geometrie-4lete-2027-v1-q18','cermat-geometrie-4lete-2027-v1',18,'{"instruction":"Žebřík délky 13 m stojí 5 m od stěny. Do jaké výšky v metrech dosáhne?","category":"Pythagorova věta","hint":"Žebřík je přepona."}','[{"id":"a","label":"12"},{"id":"b","label":"14"},{"id":"c","label":"10"},{"id":"d","label":"16"}]','a','h = √(13² − 5²) = 12 m.',2),
('cermat-geometrie-4lete-2027-v1-q19','cermat-geometrie-4lete-2027-v1',19,'{"instruction":"Kružnice má poloměr 5 cm. Jaký je koeficient před π v jejím obvodu (o = ?π cm)?","category":"Kruh a kružnice","hint":"Počítáš koeficient před π."}','[{"id":"a","label":"13"},{"id":"b","label":"7"},{"id":"c","label":"16"},{"id":"d","label":"10"}]','d','o = 2πr = 10π cm.',2),
('cermat-geometrie-4lete-2027-v1-q20','cermat-geometrie-4lete-2027-v1',20,'{"instruction":"Kruh má poloměr 4 cm. Jaký je koeficient před π v jeho obsahu (S = ?π cm²)?","category":"Kruh a kružnice","hint":"Poloměr umocni na druhou."}','[{"id":"a","label":"20"},{"id":"b","label":"12"},{"id":"c","label":"16"},{"id":"d","label":"24"}]','c','S = πr² = 16π cm².',2),
('cermat-geometrie-4lete-2027-v1-q21','cermat-geometrie-4lete-2027-v1',21,'{"instruction":"Průměr kruhu je 18 cm. Urči poloměr v cm.","category":"Kruh a kružnice","hint":"Průměr je dvojnásobek poloměru."}','[{"id":"a","label":"10"},{"id":"b","label":"9"},{"id":"c","label":"8"},{"id":"d","label":"11"}]','b','r = d/2 = 9 cm.',2),
('cermat-geometrie-4lete-2027-v1-q22','cermat-geometrie-4lete-2027-v1',22,'{"instruction":"Kruh má obsah 49π cm². Urči jeho poloměr v cm.","category":"Kruh a kružnice","hint":"S = πr²."}','[{"id":"a","label":"7"},{"id":"b","label":"9"},{"id":"c","label":"5"},{"id":"d","label":"11"}]','a','r² = 49, tedy r = 7 cm.',2),
('cermat-geometrie-4lete-2027-v1-q23','cermat-geometrie-4lete-2027-v1',23,'{"instruction":"Obvod kružnice je 24π cm. Urči poloměr v cm.","category":"Kruh a kružnice","hint":"Vyděl 2π."}','[{"id":"a","label":"15"},{"id":"b","label":"9"},{"id":"c","label":"18"},{"id":"d","label":"12"}]','d','2πr = 24π, takže r = 12 cm.',2),
('cermat-geometrie-4lete-2027-v1-q24','cermat-geometrie-4lete-2027-v1',24,'{"instruction":"Kruh má průměr 14 cm. Jaký je koeficient před π v jeho obsahu (S = ?π cm²)?","category":"Kruh a kružnice","hint":"Nejdřív přepočítej průměr na poloměr."}','[{"id":"a","label":"53"},{"id":"b","label":"45"},{"id":"c","label":"49"},{"id":"d","label":"57"}]','c','r = 7 cm a S = 49π cm².',2),
('cermat-geometrie-4lete-2027-v1-q25','cermat-geometrie-4lete-2027-v1',25,'{"instruction":"Na plánu 1 : 500 měří úsek 6 cm. Urči skutečnou vzdálenost v metrech.","category":"Podobnost a měřítko","hint":"Pozor na převod cm na m."}','[{"id":"a","label":"31"},{"id":"b","label":"30"},{"id":"c","label":"29"},{"id":"d","label":"32"}]','b','6 × 500 = 3000 cm = 30 m.',2),
('cermat-geometrie-4lete-2027-v1-q26','cermat-geometrie-4lete-2027-v1',26,'{"instruction":"Na mapě 1 : 25 000 je úsek 4 cm. Kolik kilometrů měří ve skutečnosti?","category":"Podobnost a měřítko","hint":"100 000 cm = 1 km."}','[{"id":"a","label":"1"},{"id":"b","label":"3"},{"id":"c","label":"-1"},{"id":"d","label":"5"}]','a','4 × 25 000 = 100 000 cm = 1 km.',2),
('cermat-geometrie-4lete-2027-v1-q27','cermat-geometrie-4lete-2027-v1',27,'{"instruction":"Dvě podobné figury mají poměr stran 4 : 10. Kratší figura má stranu 8 cm. Urči odpovídající stranu větší figury v cm.","category":"Podobnost a měřítko","hint":"Odpovídající délky se násobí poměrem podobnosti."}','[{"id":"a","label":"23"},{"id":"b","label":"17"},{"id":"c","label":"26"},{"id":"d","label":"20"}]','d','k = 10/4 = 2,5; 8 × 2,5 = 20 cm.',2),
('cermat-geometrie-4lete-2027-v1-q28','cermat-geometrie-4lete-2027-v1',28,'{"instruction":"Při podobnosti s koeficientem k = 3 má menší obrazec obsah 12 cm². Urči obsah většího v cm².","category":"Podobnost a měřítko","hint":"Plocha roste s druhou mocninou měřítka."}','[{"id":"a","label":"112"},{"id":"b","label":"104"},{"id":"c","label":"108"},{"id":"d","label":"116"}]','c','Obsah se mění k²: 12 × 3² = 108 cm².',2),
('cermat-geometrie-4lete-2027-v1-q29','cermat-geometrie-4lete-2027-v1',29,'{"instruction":"Podobný útvar je zvětšen v poměru 3 : 2. Původní obvod je 24 cm. Jaký je nový obvod v cm?","category":"Podobnost a měřítko","hint":"Obvody se mění stejně jako délky."}','[{"id":"a","label":"37"},{"id":"b","label":"36"},{"id":"c","label":"35"},{"id":"d","label":"38"}]','b','24 × 3/2 = 36 cm.',2),
('cermat-geometrie-4lete-2027-v1-q30','cermat-geometrie-4lete-2027-v1',30,'{"instruction":"Trojúhelníky jsou podobné. Kratší strana prvního má 3 cm, druhého 9 cm. Delší odpovídající strana prvního má 5 cm. Urči druhou v cm.","category":"Podobnost a měřítko","hint":"Použij shodný poměr odpovídajících stran."}','[{"id":"a","label":"15"},{"id":"b","label":"17"},{"id":"c","label":"13"},{"id":"d","label":"19"}]','a','Poměr je 9/3 = 3; 5 × 3 = 15 cm.',2),
('cermat-geometrie-4lete-2027-v1-q31','cermat-geometrie-4lete-2027-v1',31,'{"instruction":"Krychle má hranu 4 cm. Urči objem v cm³.","category":"Tělesa a sítě","hint":"Objem krychle je a³."}','[{"id":"a","label":"67"},{"id":"b","label":"61"},{"id":"c","label":"70"},{"id":"d","label":"64"}]','d','V = 4³ = 64 cm³.',2),
('cermat-geometrie-4lete-2027-v1-q32','cermat-geometrie-4lete-2027-v1',32,'{"instruction":"Krychle má hranu 6 cm. Urči povrch v cm².","category":"Tělesa a sítě","hint":"Krychle má šest shodných stěn."}','[{"id":"a","label":"220"},{"id":"b","label":"212"},{"id":"c","label":"216"},{"id":"d","label":"224"}]','c','S = 6 × 6² = 216 cm².',2),
('cermat-geometrie-4lete-2027-v1-q33','cermat-geometrie-4lete-2027-v1',33,'{"instruction":"Kolmý hranol má obsah podstavy 24 cm² a výšku 7 cm. Urči objem v cm³.","category":"Tělesa a sítě","hint":"Objem hranolu = podstava × výška."}','[{"id":"a","label":"169"},{"id":"b","label":"168"},{"id":"c","label":"167"},{"id":"d","label":"170"}]','b','V = Sp × v = 24 × 7 = 168 cm³.',2),
('cermat-geometrie-4lete-2027-v1-q34','cermat-geometrie-4lete-2027-v1',34,'{"instruction":"Kvádr má rozměry 3, 4 a 5 cm. Urči objem v cm³.","category":"Tělesa a sítě","hint":"Vynásob délky tří hran."}','[{"id":"a","label":"60"},{"id":"b","label":"62"},{"id":"c","label":"58"},{"id":"d","label":"64"}]','a','V = 3 × 4 × 5 = 60 cm³.',2),
('cermat-geometrie-4lete-2027-v1-q35','cermat-geometrie-4lete-2027-v1',35,'{"instruction":"Kvádr má hrany 3, 4 a 5 cm. Urči povrch v cm².","category":"Tělesa a sítě","hint":"S = 2(ab + bc + ac)."}','[{"id":"a","label":"97"},{"id":"b","label":"91"},{"id":"c","label":"100"},{"id":"d","label":"94"}]','d','S = 2(12 + 20 + 15) = 94 cm².',2),
('cermat-geometrie-4lete-2027-v1-q36','cermat-geometrie-4lete-2027-v1',36,'{"instruction":"Kolik hran má kvádr?","category":"Tělesa a sítě","hint":"Spočítej 4 nahoře, 4 dole a 4 svisle."}','[{"id":"a","label":"16"},{"id":"b","label":"8"},{"id":"c","label":"12"},{"id":"d","label":"20"}]','c','Kvádr má 12 hran, 8 vrcholů a 6 stěn.',2),
('cermat-geometrie-4lete-2027-v1-q37','cermat-geometrie-4lete-2027-v1',37,'{"instruction":"Může vzniknout trojúhelník se stranami 4 cm, 5 cm a 10 cm? Odpověz 1 = ano, 0 = ne.","category":"Konstrukce a úsudek","hint":"Součet dvou kratších stran musí být větší než nejdelší."}','[{"id":"a","label":"1"},{"id":"b","label":"0"},{"id":"c","label":"-1"},{"id":"d","label":"2"}]','b','4 + 5 = 9 < 10, trojúhelníková nerovnost neplatí.',2),
('cermat-geometrie-4lete-2027-v1-q38','cermat-geometrie-4lete-2027-v1',38,'{"instruction":"Kolik os souměrnosti má obdélník, který není čtvercem?","category":"Konstrukce a úsudek","hint":"Nepleť si osy a úhlopříčky."}','[{"id":"a","label":"2"},{"id":"b","label":"4"},{"id":"c","label":"0"},{"id":"d","label":"6"}]','a','Má vodorovnou a svislou osu procházející středy protilehlých stran.',2),
('cermat-geometrie-4lete-2027-v1-q39','cermat-geometrie-4lete-2027-v1',39,'{"instruction":"Kolik os souměrnosti má čtverec?","category":"Konstrukce a úsudek","hint":"Čtverec má čtyři osy souměrnosti."}','[{"id":"a","label":"7"},{"id":"b","label":"1"},{"id":"c","label":"10"},{"id":"d","label":"4"}]','d','Dvě osy středem stran, dvě úhlopříčky.',2),
('cermat-geometrie-4lete-2027-v1-q40','cermat-geometrie-4lete-2027-v1',40,'{"instruction":"Nejvýše v kolika bodech se mohou protínat dvě různé kružnice?","category":"Konstrukce a úsudek","hint":"Možnosti jsou 0, 1 nebo 2."}','[{"id":"a","label":"6"},{"id":"b","label":"-2"},{"id":"c","label":"2"},{"id":"d","label":"10"}]','c','Dvě různé kružnice mají nejvýše dva společné body.',2),
('cermat-geometrie-4lete-2027-v1-q41','cermat-geometrie-4lete-2027-v1',41,'{"instruction":"Kolik vrcholů má trojboký hranol?","category":"Konstrukce a úsudek","hint":"Dvě podstavy, každá se třemi vrcholy."}','[{"id":"a","label":"7"},{"id":"b","label":"6"},{"id":"c","label":"5"},{"id":"d","label":"8"}]','b','Na každé ze dvou trojúhelníkových podstav jsou tři vrcholy.',2),
('cermat-geometrie-4lete-2027-v1-q42','cermat-geometrie-4lete-2027-v1',42,'{"instruction":"Kolik stupňů má jeden vnitřní úhel rovnostranného trojúhelníku?","category":"Konstrukce a úsudek","hint":"Všechny tři úhly jsou stejné."}','[{"id":"a","label":"60"},{"id":"b","label":"62"},{"id":"c","label":"58"},{"id":"d","label":"64"}]','a','180/3 = 60°.',2);
